const info={orbit:{title:'Орбита',model:'ChatGPT',code:`// Орбита: остановить спутник в секторе\nconst target = { angle: 0.8, size: 0.4 };\nlet angle = 0;\n\nfunction update(delta) {\n  angle += delta * speed;\n  drawOrbit(angle, target);\n}\n\nbutton.onclick = () => {\n  const hit = isInside(angle, target);\n  score += hit ? 1 : 0;\n  showResult(hit);\n};`},tower:{title:'Башня',model:'Claude',code:`// Башня: каждый блок должен удержаться\nlet blocks = [createBase()];\nlet moving = createBlock();\n\nfunction placeBlock() {\n  const overlap = intersect(moving, last(blocks));\n  if (overlap.width <= 0) return gameOver();\n  blocks.push(overlap);\n  moving = createBlock(overlap.width);\n  drawTower(blocks);\n}\n\nbutton.onclick = placeBlock;`},reaction:{title:'Реакция',model:'Gemini',code:`// Реакция: дождаться зелёного сигнала\nconst delay = 1500 + Math.random() * 2500;\nlet readyAt = null;\n\nsetTimeout(() => {\n  readyAt = performance.now();\n  showSignal('green');\n}, delay);\n\nbutton.onclick = () => {\n  if (!readyAt) return showTooEarly();\n  showTime(performance.now() - readyAt);\n};`}};
const dialog=document.getElementById('game-dialog'),frame=document.getElementById('game-frame');let opener=null;document.querySelectorAll('[data-game]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.game;opener=b;document.getElementById('dialog-title').textContent=info[key].title;document.getElementById('dialog-author').textContent='Демонстрация участия '+info[key].model;frame.src='play.html?game='+key;frame.title='Игра '+info[key].title;dialog.showModal();document.getElementById('close-game').focus()}));document.getElementById('close-game').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{frame.removeAttribute('src');opener?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
window.addEventListener('message',event=>{if(event.source===frame.contentWindow&&event.data?.type==='commit-zero-close'&&dialog.open)dialog.close()});
const code=document.getElementById('code'),run=document.getElementById('run'),statusText=document.getElementById('status-text'),status=document.getElementById('process-status');let selected='orbit',timer=null,index=0,phase=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)');function stop(){clearTimeout(timer);timer=null;run.disabled=false;run.textContent='Показать процесс';status.className='status'}function select(key){stop();selected=key;document.getElementById('filename').textContent=key+'.js';code.textContent=info[key].code.split('\n').slice(0,3).join('\n')+'\n\n// Нажми «Показать процесс»';statusText.textContent='Готов к демонстрации';document.querySelectorAll('[data-model]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.model===key)))}document.querySelectorAll('[data-model]').forEach(b=>b.onclick=()=>select(b.dataset.model));
function finish(){status.className='status done';statusText.textContent='Демонстрация завершена · игра доступна выше';run.disabled=false;run.textContent='Повторить';timer=null}function tick(){const source=info[selected].code;index=Math.min(source.length,index+5);code.textContent=source.slice(0,index);const p=index/source.length;if(p>.7&&phase<2){phase=2;statusText.textContent='Добавляет управление кнопкой…'}else if(p>.25&&phase<1){phase=1;statusText.textContent='Пишет игровую механику…'}code.parentElement.scrollTop=code.parentElement.scrollHeight;if(index<source.length)timer=setTimeout(tick,35);else{statusText.textContent='Показывает проверку запуска…';timer=setTimeout(finish,900)}}run.onclick=()=>{stop();phase=0;index=0;run.disabled=true;run.textContent='Выполняется…';status.className='status running';statusText.textContent='Готовит структуру игры…';if(reduced.matches){code.textContent=info[selected].code;finish()}else{code.textContent='';timer=setTimeout(tick,400)}};document.addEventListener('visibilitychange',()=>{if(document.hidden&&timer){stop();statusText.textContent='Показ приостановлен. Можно начать заново.'}});select('orbit');
